create extension if not exists pgcrypto;create table if not exists public.settings(user_id uuid primary key references auth.users(id) on delete cascade,planned_salary bigint not null default 0,daily_budget bigint not null default 0,rent_budget bigint not null default 0,incidental_budget bigint not null default 0,starting_debt bigint not null default 0,planned_debt_payment bigint not null default 0,savings_goal bigint not null default 0,salary_day integer not null default 15 check(salary_day between 1 and 28),plan_start_date date not null default '2026-09-15',initial_savings bigint not null default 0,t13_amount bigint not null default 0,t13_date date);create table if not exists public.transactions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,occurred_on date not null,description text not null,category text not null check(category in('Ăn uống','Cafe/Giải trí','Đi lại/Xăng','Mua sắm','Khác','Trọ','Phát sinh','Trả nợ','Lương','Thưởng','Thu nhập khác')),type text not null check(type in('Thu','Chi')),amount bigint not null check(amount>0),note text,created_at timestamptz not null default now());create index if not exists transactions_user_date_idx on public.transactions(user_id,occurred_on desc);alter table public.settings enable row level security;alter table public.transactions enable row level security;drop policy if exists settings_select_own on public.settings;drop policy if exists settings_insert_own on public.settings;drop policy if exists settings_update_own on public.settings;drop policy if exists transactions_select_own on public.transactions;drop policy if exists transactions_insert_own on public.transactions;drop policy if exists transactions_update_own on public.transactions;drop policy if exists transactions_delete_own on public.transactions;create policy settings_select_own on public.settings for select using(auth.uid()=user_id);create policy settings_insert_own on public.settings for insert with check(auth.uid()=user_id);create policy settings_update_own on public.settings for update using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy transactions_select_own on public.transactions for select using(auth.uid()=user_id);create policy transactions_insert_own on public.transactions for insert with check(auth.uid()=user_id);create policy transactions_update_own on public.transactions for update using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy transactions_delete_own on public.transactions for delete using(auth.uid()=user_id);
create table if not exists public.debts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,principal bigint not null check(principal>0),created_at timestamptz not null default now());alter table public.transactions add column if not exists debt_id uuid references public.debts(id) on delete set null;create index if not exists debts_user_idx on public.debts(user_id);create index if not exists transactions_debt_idx on public.transactions(debt_id);alter table public.debts enable row level security;drop policy if exists debts_select_own on public.debts;drop policy if exists debts_insert_own on public.debts;drop policy if exists debts_update_own on public.debts;drop policy if exists debts_delete_own on public.debts;create policy debts_select_own on public.debts for select using(auth.uid()=user_id);create policy debts_insert_own on public.debts for insert with check(auth.uid()=user_id);create policy debts_update_own on public.debts for update using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy debts_delete_own on public.debts for delete using(auth.uid()=user_id);